sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float spacing;
uniform float angle;
uniform float sharpness;
uniform float wobble;
uniform float wobbleScale;
layout(color) uniform half4 inkColor;
layout(color) uniform half4 paperColor;
uniform float invert;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float vnoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + float2(1.0, 0.0));
    float c = hash21(i + float2(0.0, 1.0));
    float d = hash21(i + float2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float2 rot2(float2 p, float a) {
    float s = sin(a);
    float c = cos(a);
    return float2(p.x * c - p.y * s, p.x * s + p.y * c);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float l = luma(s);
    if (invert > 0.5) l = 1.0 - l;
    float2 p = rot2(coord, -radians(angle));
    float d = p.y / spacing + (vnoise(coord / wobbleScale) - 0.5) * wobble * 4.0;
    float f = abs(fract(d) - 0.5);
    float t = (1.0 - l) * 0.5;
    float soft = mix(0.25, 0.015, sharpness);
    float m = 1.0 - smoothstep(t - soft, t + soft, f);
    float3 o = mix(float3(paperColor.rgb), float3(inkColor.rgb), m);
    return fin(c, float4(o * c.a, c.a), opacity);
}
